/**
 * Body of POST /api/sheets/{sheet}/people and PUT /api/sheets/{sheet}/people/{person}. On a PUT, the
 * version is the one the editor loaded (null to save regardless), and the grade is recorded from the
 * from-date (yyyy-mm-dd; blank for the sheet's today). On a POST the grade applies from the beginning of time.
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a valid from-date: " + from);
            }
        }
        body.set(new PersonRequest(name, grade, request.version(), from.isEmpty() ? null : from));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class BuildPerson {
    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val PersonRequest request, People people, Audit audit, Rollup rollup, Out<Person> person)
            throws DuplicatePersonNameException {
        Rollup.Snapshot before = rollup.take(sheet);
        Person added = people.add(sheet, request.name(), request.grade());
        person.set(added);
        audit.record("PERSON_ADDED sheet=" + sheet + " by=" + user + " name=" + added.name() + " grade="
                + added.grade());
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SavePerson {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val PersonRequest request, People people, SheetClock clock, Audit audit, Rollup rollup)
            throws DuplicatePersonNameException, StalePersonException {
        // Saving over a version other than the one the editor loaded is refused, and writes nothing.
        long loaded = request.version() == null ? person.version() : request.version();
        if (loaded != person.version()) {
            throw new StalePersonException(person.id());
        }
        Rollup.Snapshot before = rollup.take(sheet);
        people.update(sheet, new Person(person.id(), request.name(), person.grade(), loaded, person.retiredFrom(),
                person.holds(), person.grades()));
        // The form's grade is recorded from its from-date (the sheet's today when blank), keeping the ones already
        // recorded; leaving the grade as the row showed it, with the from-date blank, records nothing.
        if (request.gradeFrom() != null || !request.grade().equals(person.grade())) {
            LocalDate from = request.gradeFrom() == null ? clock.today(sheet) : LocalDate.parse(request.gradeFrom());
            people.setGrade(person.id(), request.grade(), from);
        }
        Person saved = people.find(sheet, person.id());
        audit.record("PERSON_EDITED sheet=" + sheet + " by=" + user + " name=" + saved.name() + " grade="
                + saved.grade());
        rollup.record(sheet, user, before);
    }
}

